import{Ft as e,St as t,bt as n,ht as r,qt as i,t as a,vt as o,xt as s,zt as c}from"./chunks/framework.B0CLzZNn.js";var l=JSON.parse(`{"title":"伪装推荐插件","description":"","frontmatter":{},"headers":[],"relativePath":"guide/best-practice/character-recommended-plugins.md","filePath":"v1/guide/best-practice/character-recommended-plugins.md","lastUpdated":1793342047000}`),u={name:`guide/best-practice/character-recommended-plugins.md`};function d(a,l,u,d,f,p){let m=c(`NolebasePageProperties`),h=c(`VPNolebaseInlineLinkPreview`),g=c(`NolebaseGitChangelog`);return e(),o(`div`,null,[l[6]||=r(`h1`,{id:`伪装推荐插件`,tabindex:`-1`},[s(`伪装推荐插件 `),r(`a`,{class:`header-anchor`,href:`#伪装推荐插件`,"aria-label":`Permalink to “伪装推荐插件”`},`​`)],-1),t(m),l[7]||=n(`<p>本页面列出了搭配 ChatLuna 伪装插件使用时推荐安装的插件，按模板项目中的层级分类整理。</p><p>如果你通过 ChatLuna Koishi 模板部署，则下列大部分插件已被安装、配置完成，仅需关注 <code>chatluna-toolbox</code> 的配置。</p><p><strong>不要忘记在修改插件配置后，点击右上角的“重载配置”按钮</strong></p><h2 id="基础" tabindex="-1">基础 <a class="header-anchor" href="#基础" aria-label="Permalink to “基础”">​</a></h2><p>ChatLuna 核心组件，提供基本的对话能力。</p><h3 id="chatluna" tabindex="-1">chatluna <a class="header-anchor" href="#chatluna" aria-label="Permalink to “chatluna”">​</a></h3><p>ChatLuna 主插件，提供对话系统核心功能。</p><p><strong>推荐配置：</strong></p><ul><li>在&quot;对话行为选项&quot;中启用 <code>attachForwardMsgIdToContext</code>（如需使用合并转发读取功能）</li></ul><h3 id="chatluna-character" tabindex="-1">chatluna-character <a class="header-anchor" href="#chatluna-character" aria-label="Permalink to “chatluna-character”">​</a></h3><p>基于 Prompt 工程，尝试让大语言模型在群内伪装成群友对话。</p><p><strong>推荐配置：</strong></p><ul><li>在对应会话配置的&quot;上下文&quot;中启用 <code>enableMessageId</code>（如需使用合并转发读取功能）</li><li>如果你在使用官方 Bot 进行私聊，请开启 Koishi 插件 <code>inspect</code>，并向 Bot 发送 <code>inspect</code>，将其中&quot;用户 ID&quot;的值填写至&quot;应用到的私聊&quot;配置中</li></ul><h3 id="chatluna-storage-service" tabindex="-1">chatluna-storage-service <a class="header-anchor" href="#chatluna-storage-service" aria-label="Permalink to “chatluna-storage-service”">​</a></h3><blockquote><p>强烈建议安装</p></blockquote><p>提供文件存储服务，同时可以防止 QQ 图床、文件的链接过期。</p><p><strong>推荐配置：</strong></p><ul><li>将&quot;存储后端类型&quot;改为&quot;本地文件存储&quot;</li><li>将&quot;Koishi 在公网或者局域网中的路径&quot;改为你的环境中实际的路径，确保此路径可以被你的 NapCat 或 LLBot 正常访问： <ul><li><strong>Linux Docker 部署：</strong><ul><li>若 Koishi 与你的 NapCat 或 LLBot 使用 Docker 部署在同一个容器中，请尝试保持默认地址 <code>http://127.0.0.1:5140</code>，不要修改</li><li>若 Koishi 与你的 NapCat 或 LLBot 使用 Docker 部署在不同容器中、但使用同一个 Docker 网桥时，可以填写 <code>http://koishi:5140</code>，5140 为你的 Koishi 容器内端口</li><li>不建议使用容器在宿主机的内网 IP 连接，因为容器的内网 IP 可能会在重启后重新分配，导致原有连接断开</li></ul></li><li><strong>其他部署：</strong><ul><li>其他部署方案（如 Windows），请尝试保持默认地址 <code>http://127.0.0.1:5140</code>，不要修改</li></ul></li></ul></li></ul><h3 id="chatluna-multimodal-service" tabindex="-1">chatluna-multimodal-service <a class="header-anchor" href="#chatluna-multimodal-service" aria-label="Permalink to “chatluna-multimodal-service”">​</a></h3><blockquote><p>使用 Gemini 或不支持图像输入的模型时推荐</p></blockquote><p>提供图像描述服务、图像及文件（含视频）读取/描述工具。</p><p><strong>推荐配置：</strong></p><ul><li>若使用 Gemini，可以启用 <code>enableImageReadTool</code>、<code>enableFileReadTool</code></li><li>若使用不支持图像输入的模型（如 DeepSeek），可以启用 <code>enableContextImageDescription</code>、<code>enableImageReadTool</code>，并在图像描述服务设置中配置一个支持图像输入的模型以生成图像描述</li></ul><h2 id="扩展" tabindex="-1">扩展 <a class="header-anchor" href="#扩展" aria-label="Permalink to “扩展”">​</a></h2><p>增强 ChatLuna 功能的扩展插件。</p><h3 id="chatluna-plugin-common" tabindex="-1">chatluna-plugin-common <a class="header-anchor" href="#chatluna-plugin-common" aria-label="Permalink to “chatluna-plugin-common”">​</a></h3><p>提供一些通用的工具，包括预设中用到的群管工具。</p><p><strong>推荐配置：</strong></p><ul><li>只启用&quot;群管插件&quot;，其他选项全部关闭</li><li>在&quot;群管插件配置&quot;中配置好： <ul><li>&quot;允许使用群管功能的成员 ID 列表&quot;（可以要求 Bot 使用群管功能的人）</li><li>&quot;允许使用群管功能的群 ID 白名单&quot;</li></ul></li></ul><h3 id="chatluna-toolbox" tabindex="-1">chatluna-toolbox <a class="header-anchor" href="#chatluna-toolbox" aria-label="Permalink to “chatluna-toolbox”">​</a></h3><p>提供戳一戳、贴表情、撤回消息等功能。</p><p><strong>推荐配置：</strong></p><ul><li>在&quot;原生工具&quot;中启用&quot;NapCat OneBot&quot;或&quot;LLBot OneBot&quot;中你使用的协议</li><li>&quot;XML 工具&quot;配置： <ul><li><strong>非工具调用预设：</strong> 启用除了 <code>injectXmlToolAsReplyTool</code> 和 <code>enableBanXmlTool</code> 之外的全部选项</li><li><strong>工具调用预设：</strong> 启用除了 <code>enableBanXmlTool</code> 之外的全部选项</li></ul></li><li>其他选项全部关闭</li></ul><h3 id="chatluna-forward-msg" tabindex="-1">chatluna-forward-msg <a class="header-anchor" href="#chatluna-forward-msg" aria-label="Permalink to “chatluna-forward-msg”">​</a></h3><p>提供合并转发记录读取、发送功能。</p><p><strong>推荐配置：</strong></p><ul><li>在&quot;协议选择&quot;中选择你使用的协议</li><li>在&quot;图片描述服务&quot;中选择一个多模态模型</li><li>在 <code>chatluna</code> 插件的&quot;对话行为选项&quot;中启用：<code>attachForwardMsgIdToContext</code></li><li>在 <code>chatluna-character</code> 插件对应会话配置的&quot;上下文&quot;中启用：<code>enableMessageId</code></li></ul><h3 id="chatluna-long-memory" tabindex="-1">chatluna-long-memory <a class="header-anchor" href="#chatluna-long-memory" aria-label="Permalink to “chatluna-long-memory”">​</a></h3><p>提供长期记忆功能。</p><p><strong>推荐配置：</strong></p><ul><li>将所有&quot;长期记忆引擎配置&quot;改为 <code>Basic</code></li><li>&quot;启用的记忆检索层&quot;只勾选&quot;群组层&quot;</li></ul><h3 id="chatluna-memes" tabindex="-1">chatluna-memes <a class="header-anchor" href="#chatluna-memes" aria-label="Permalink to “chatluna-memes”">​</a></h3><p>提供表情包发送功能，是 fork lumia1998/memesluna 后修改并独立发布的插件，首次启动时会自动迁移 memesluna 的数据。</p><p><strong>推荐配置：</strong></p><ul><li>在控制台侧栏的 ChatLuna Memes 页面管理表情包，并在&quot;配置&quot;中开启 ChatLuna 注入</li><li>预设中使用变量 <code>{chatluna_memes}</code>（原 <code>{memesluna}</code>）</li><li>建议自行准备一张“拒绝”类型的表情包以应对不友好的用户</li></ul><h3 id="chatluna-llm-web-search" tabindex="-1">chatluna-llm-web-search <a class="header-anchor" href="#chatluna-llm-web-search" aria-label="Permalink to “chatluna-llm-web-search”">​</a></h3><p>提供全网/X 平台搜索、URL 读取功能。</p><h3 id="chatluna-qweather" tabindex="-1">chatluna-qweather <a class="header-anchor" href="#chatluna-qweather" aria-label="Permalink to “chatluna-qweather”">​</a></h3><p>提供天气查询功能。</p><h3 id="chatluna-social-media-reader" tabindex="-1">chatluna-social-media-reader <a class="header-anchor" href="#chatluna-social-media-reader" aria-label="Permalink to “chatluna-social-media-reader”">​</a></h3><p>提供 B 站、小红书视频/帖子读取功能。</p><h3 id="chatluna-google-reverse-image-search" tabindex="-1">chatluna-google-reverse-image-search <a class="header-anchor" href="#chatluna-google-reverse-image-search" aria-label="Permalink to “chatluna-google-reverse-image-search”">​</a></h3><p>提供高质量的以图搜图功能。</p><h2 id="高级" tabindex="-1">高级 <a class="header-anchor" href="#高级" aria-label="Permalink to “高级”">​</a></h2><p>提供 Agent、媒体生成、知识库等高级能力。</p><h3 id="chatluna-agent" tabindex="-1">chatluna-agent <a class="header-anchor" href="#chatluna-agent" aria-label="Permalink to “chatluna-agent”">​</a></h3><p>提供丰富的 Agent 相关能力（MCP、Skill、子 Agent、沙盒终端等），可控制工具在任意会话中的权限、进行文件处理、使用子 Agent 节约时间与 token 开销。</p><p><strong>推荐配置：</strong></p>`,58),r(`ul`,null,[r(`li`,null,[l[1]||=s(`参考 `,-1),t(h,{href:`./../../ecosystem/plugin/extension-agent.html`},{default:i(()=>[...l[0]||=[s(`Agent 配置`,-1)]]),_:1}),l[2]||=s(` 进行配置`,-1)])]),l[8]||=r(`h3`,{id:`media-luna`,tabindex:`-1`},[s(`media-luna `),r(`a`,{class:`header-anchor`,href:`#media-luna`,"aria-label":`Permalink to “media-luna”`},`​`)],-1),l[9]||=r(`p`,null,`提供丰富的媒体生成能力（包括文本生成图片、图片生成图片、音频生成、视频生成），搭配适当的配置可以实现用 AI 生成图片等需求。`,-1),l[10]||=r(`p`,null,`该项目的 WebUI 有待改进。`,-1),l[11]||=r(`h3`,{id:`chatluna-vector-store-service`,tabindex:`-1`},[s(`chatluna-vector-store-service `),r(`a`,{class:`header-anchor`,href:`#chatluna-vector-store-service`,"aria-label":`Permalink to “chatluna-vector-store-service”`},`​`)],-1),l[12]||=r(`p`,null,`向量数据库服务，为知识库和长期记忆提供底层支持。`,-1),l[13]||=r(`p`,null,[r(`strong`,null,`推荐配置：`)],-1),r(`ul`,null,[r(`li`,null,[l[4]||=s(`参考 `,-1),t(h,{href:`./../configure-vector-database/introduction.html`},{default:i(()=>[...l[3]||=[s(`向量数据库`,-1)]]),_:1}),l[5]||=s(` 进行配置`,-1)])]),l[14]||=n(`<h2 id="其他插件" tabindex="-1">其他插件 <a class="header-anchor" href="#其他插件" aria-label="Permalink to “其他插件”">​</a></h2><p>增强 Koishi 的使用体验。</p><h3 id="sidebar-manager" tabindex="-1">sidebar-manager <a class="header-anchor" href="#sidebar-manager" aria-label="Permalink to “sidebar-manager”">​</a></h3><p>帮助你折叠不需要的 Koishi 侧栏图标。</p><h3 id="logger-next" tabindex="-1">logger-next <a class="header-anchor" href="#logger-next" aria-label="Permalink to “logger-next”">​</a></h3><p>更好的 Koishi 日志插件，优化了日志性能,虚拟滚动,更好的滚动体验。</p><h3 id="without-assignee" tabindex="-1">without-assignee <a class="header-anchor" href="#without-assignee" aria-label="Permalink to “without-assignee”">​</a></h3><p>解决同平台适配器接入过一个以上的账号后，Bot 无法触发响应的问题。</p><h3 id="auth-cleanup" tabindex="-1">auth-cleanup <a class="header-anchor" href="#auth-cleanup" aria-label="Permalink to “auth-cleanup”">​</a></h3><p>定期清理 Koishi 控制台的过期登录记录，避免数据库中的登录记录无限增长。</p><h3 id="ffmpeg-path" tabindex="-1">ffmpeg-path <a class="header-anchor" href="#ffmpeg-path" aria-label="Permalink to “ffmpeg-path”">​</a></h3><p>提供完善的媒体转码服务，解决部分平台/ API 无法接收/发送不受支持的文件的问题。</p><h3 id="语音服务-tts" tabindex="-1">语音服务（TTS） <a class="header-anchor" href="#语音服务-tts" aria-label="Permalink to “语音服务（TTS）”">​</a></h3><p>提供 TTS 服务用于发送语音。</p><p><strong>推荐配置：</strong></p><ul><li>语音服务请自行寻找合适的插件或尝试使用 <code>media-luna</code></li><li>如果无需使用，也可以直接删去预设中 <code>voice</code> 相关描述</li></ul>`,16),t(g)])}var f=a(u,[[`render`,d]]);export{l as __pageData,f as default};